 * @method rectMode
 * @param  {Constant} mode either CORNER, CORNERS, CENTER, or RADIUS
 * @chainable
 *
 * @example
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
 *
 *   background(200);
 *
 *   rectMode(CORNER);
 *   fill(255);
 *   rect(25, 25, 50, 50);
 *
 *   rectMode(CORNERS);
 *   fill(100);
 *   rect(25, 25, 50, 50);
 *
 *   describe('A small gray square drawn at the top-left corner of a white square.');
 * }
 * </code>
 * </div>
 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
 *
 *   background(200);
 *
 *   rectMode(RADIUS);
 *   fill(255);
 *   rect(50, 50, 30, 30);
 *
 *   rectMode(CENTER);
 *   fill(100);
 *   rect(50, 50, 30, 30);
 *
 *   describe('A small gray square drawn at the center of a white square.');
 * }
 * </code>
 * </div>
 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
 *
 *   background(200);
 *
 *   rectMode(CORNER);
 *   fill(255);
 *   square(25, 25, 50);
 *
 *   describe('A white square.');
 * }
 * </code>
 * </div>
 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
 *
 *   background(200);
 *
 *   rectMode(RADIUS);
 *   fill(255);
 *   square(50, 50, 30);
 *
 *   rectMode(CENTER);
 *   fill(100);
 *   square(50, 50, 30);
 *
 *   describe('A small gray square drawn at the center of a white square.');
 * }
 * </code>
