 *   strokeWeight(10);
 *   strokeJoin(BEVEL);
 *
 *   // Draw the line.
 *   beginShape();
 *   vertex(35, 20);
 *   vertex(65, 50);
 *   vertex(35, 80);
 *   endShape();
 *
 *   describe('A right-facing arrowhead shape with a flat tip in center of canvas.');
 * }
 * </code>
 * </div>
 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
