 *   strokeWeight(10);
 *   strokeJoin(ROUND);
 *
 *   // Draw the line.
 *   beginShape();
 *   vertex(35, 20);
 *   vertex(65, 50);
 *   vertex(35, 80);
 *   endShape();
 *
 *   describe('A right-facing arrowhead shape with a rounded tip in center of canvas.');
 * }
