 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
 *
 *   background(200);
 *
 *   // Start drawing the shape.
 *   // Draw a series of quadrilaterals.
 *   beginShape(QUAD_STRIP);
 *
 *   // Add vertices.
 *   vertex(30, 20);
 *   vertex(30, 75);
 *   vertex(50, 20);
 *   vertex(50, 75);
