 * </code>
 * </div>
 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100, WEBGL);
 *
 *   background(200);
 *
 *   // Start drawing the shape.
 *   // Draw a series of quadrilaterals.
 *   beginShape(TESS);
 *
 *   // Add the vertices.
 *   vertex(-30, -30, 0);
 *   vertex(30, -30, 0);
 *   vertex(30, -10, 0);
 *   vertex(-10, -10, 0);
 *   vertex(-10, 10, 0);
 *   vertex(30, 10, 0);
 *   vertex(30, 30, 0);
 *   vertex(-30, 30, 0);
 *
 *   // Stop drawing the shape.
 *   // Connect the first and last vertices.
