 * // Draw the face.
 * circle(0, 0, 60);
 *
 * // Style the eyes.
 * fill('white');
 *
 * // Draw the left eye.
 * ellipse(-20, -20, 30, 20);
 *
 * // Draw the right eye.
 * ellipse(20, -20, 30, 20);
 *
 * // End the drawing group.
 * pop();
 *
 * // Draw a bug.
 * let x = random(0, 100);
 * let y = random(0, 100);
 * text('🦟', x, y);
 * ```
