 *   storeItem('name', 'Feist');
 *
 *   // Store the player's score.
 *   storeItem('score', 1234);
 *
 *   describe(
 *     'The text "Feist: 1234" written in black on a gray background. The text "null: null" appears when the user double-clicks.'
 *   );
 * }
 *
 * function draw() {
 *   background(200);
 *
 *   // Style the text.
 *   textAlign(CENTER, CENTER);
 *   textSize(14);
 *
