 *
 *   describe('The text "Double-click to save" written in black on a gray background.');
 * }
 *
 * // Save the file when the user double-clicks.
 * function doubleClicked() {
 *   if (mouseX > 0 && mouseX < 100 && mouseY > 0 && mouseY < 100) {
 *     // Create an array.
 *     let data = ['0', '01', '011'];
 *
 *     // Save the text file.
 *     saveStrings(data, 'data.txt');
 *   }
 * }
 * </code>
 * </div>
 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
 *
 *   background(200);
 *
 *   // Style the text.
 *   textAlign(LEFT, CENTER);
 *   textFont('Courier New');
 *   textSize(12);
 *
 *   // Display instructions.
 *   text('Double-click to save', 5, 50, 90);
 *
 *   describe('The text "Double-click to save" written in black on a gray background.');
 * }
 *
 * // Save the file when the user double-clicks.
 * function doubleClicked() {
 *   if (mouseX > 0 && mouseX < 100 && mouseY > 0 && mouseY < 100) {
 *     // Create an array.
 *     // ASCII art courtesy Wikipedia:
 *     // https://en.wikipedia.org/wiki/ASCII_art
 *     let data = [' (\\_/) ', "(='.'=)", '(")_(")'];
 *
 *     // Save the text file.
 *     saveStrings(data, 'cat', 'txt');
 *   }
 * }
 * </code>
 * </div>
 *
 * <div>
 * <code>
 * function setup() {
 *   createCanvas(100, 100);
 *
 *   background(200);
 *
 *   // Style the text.
 *   textAlign(LEFT, CENTER);
 *   textFont('Courier New');
 *   textSize(12);
 *
 *   // Display instructions.
 *   text('Double-click to save', 5, 50, 90);
 *
 *   describe('The text "Double-click to save" written in black on a gray background.');
 * }
 *
 * // Save the file when the user double-clicks.
 * function doubleClicked() {
 *   if (mouseX > 0 && mouseX < 100 && mouseY > 0 && mouseY < 100) {
 *     // Create an array.
 *     //   +--+
 *     //  /  /|
 *     // +--+ +
 *     // |  |/
 *     // +--+
 *     let data = ['  +--+', ' /  /|', '+--+ +', '|  |/', '+--+'];
 *
 *     // Save the text file.
 *     // Use CRLF for line endings.
 *     saveStrings(data, 'box', 'txt', true);
 *   }
 * }
