 *   // Create an array of numbers.
 *   let numbers = [10, 5, 20];
 *
 *   // Calculate the maximum of the array.
 *   let m = max(numbers);
 *
 *   // Style the text.
 *   textAlign(CENTER);
 *   textSize(16);
 *
 *   // Display the max.
 *   text(m, 50, 50);
 *
 *   describe('The number 20 written in the middle of a gray square.');
 * }
 * </code>
 * </div>

* @method max
 * @param  {Number[]} nums numbers to compare.
 * @return {Number}

