 *   let d = pow(base, 1);
 *   circle(10, 10, d);
 *
 *   // Left-center.
 *   d = pow(base, 2);
 *   circle(20, 20, d);
 *
 *   // Right-center.
 *   d = pow(base, 3);
 *   circle(40, 40, d);
 *
 *   // Bottom-right.
 *   d = pow(base, 4);
