    *   drawArrow(v0, v1, 'black');
    *
    *   // Draw the red arrow.
    *   let v2 = createVector(mouseX - 50, mouseY - 50);
    *   drawArrow(v0, v2, 'red');
    *
    *   // Display the dot product.
