    * <a href="#/p5/setup">setup()</a> function.
    *
    * @method normalize
    * @chainable
    *
    * @example
    * <div>
    * <code>
    * let myGeometry;
    *
    * function setup() {
    *   createCanvas(100, 100, WEBGL);
    *
    *   // Create a very small torus.
    *   beginGeometry();
    *   torus(1, 0.25);
    *   myGeometry = endGeometry();
    *
    *   // Normalize the torus so its vertices fill
    *   // the range [-100, 100].
    *   myGeometry.normalize();
    *
    *   describe('A white torus rotates slowly against a dark gray background.');
    * }
    *
    * function draw() {
    *   background(50);
    *
    *   // Turn on the lights.
    *   lights();
    *
    *   // Rotate around the y-axis.
    *   rotateY(frameCount * 0.01);
    *
    *   // Style the torus.
    *   noStroke();
    *
    *   // Draw the torus.
    *   model(myGeometry);
    * }
    * </code>
